"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { X } from "@/components/ui/icons";

// Badge: generated by UIX from the design system. Same variants and sizes as the Figma component.

const badgeVariants = cva(
  "inline-flex items-center whitespace-nowrap gap-1-5 [&_svg]:size-[14px] [&_svg]:shrink-0 rounded-full",
  {
    variants: {
      color: {
        neutral: "",
        brand: "",
        success: "",
        warning: "",
        error: "",
      },
      appearance: {
        subtle: "",
        solid: "",
        outline: "",
      },
      size: {
        sm: "px-2 py-0-5 text-label-small",
        md: "px-[10px] py-1 text-label-medium",
      },
    },
    compoundVariants: [
      { color: "neutral", appearance: "subtle", class: "skin-keep bg-subtle text-fg-secondary" },
      { color: "neutral", appearance: "solid", class: "skin-solid bg-inverse text-fg-inverse" },
      { color: "neutral", appearance: "outline", class: "border border-line-default text-fg-secondary" },
      { color: "brand", appearance: "subtle", class: "skin-keep bg-brand-subtle text-fg-brand" },
      { color: "brand", appearance: "solid", class: "skin-solid bg-brand text-fg-on-brand" },
      { color: "brand", appearance: "outline", class: "border border-line-brand text-fg-brand" },
      { color: "success", appearance: "subtle", class: "skin-keep bg-success-subtle text-fg-success" },
      { color: "success", appearance: "solid", class: "skin-solid bg-success text-fg-on-brand" },
      { color: "success", appearance: "outline", class: "border border-line-success text-fg-success" },
      { color: "warning", appearance: "subtle", class: "skin-keep bg-warning-subtle text-fg-warning" },
      { color: "warning", appearance: "solid", class: "skin-solid bg-warning text-fg-primary" },
      { color: "warning", appearance: "outline", class: "border border-line-warning text-fg-warning" },
      { color: "error", appearance: "subtle", class: "skin-keep bg-danger-subtle text-fg-danger" },
      { color: "error", appearance: "solid", class: "skin-solid bg-danger text-fg-on-danger" },
      { color: "error", appearance: "outline", class: "border border-line-danger text-fg-danger" },
    ],
    defaultVariants: {
      color: "neutral",
      appearance: "subtle",
      size: "md",
    },
  },
);

export interface BadgeProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "color">,
    VariantProps<typeof badgeVariants> {
  /** Shows a small dot before the label. */
  dot?: boolean;
  /** Icon before the label. */
  leadingIcon?: React.ReactNode;
  /** Shows a close button and calls this when it is pressed. */
  onClose?: () => void;
}

const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  ({ className, color, appearance, size, dot = false, leadingIcon, onClose, children, ...props }, ref) => (
    <span data-slot="badge" data-kind="chip" ref={ref} className={cn(badgeVariants({ color, appearance, size }), className)} {...props}>
      {dot ? <span aria-hidden className="rounded-full bg-current size-1-5" /> : null}
      {leadingIcon}
      {children}
      {onClose ? (
        <button type="button" aria-label="Remove" onClick={onClose} className="inline-flex shrink-0 cursor-pointer rounded-full opacity-70 hover:opacity-100 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
          <X aria-hidden />
        </button>
      ) : null}
    </span>
  ),
);
Badge.displayName = "Badge";

export { Badge, badgeVariants };
